package org.taku.tryon.realtime;import android.os.Bundle;import android.content.Intent;public class TryOnActivity extends android.app.Activity{public static int unsafeParentEnvelopes,creates,resumes,pauses;private void inspect(){Intent intent=getIntent();if(intent==null||intent.getAction()!=null||intent.getExtras()!=null&&!intent.getExtras().isEmpty())unsafeParentEnvelopes++;}public void onCreate(Bundle state){creates++;inspect();super.onCreate(state);}protected void onResume(){resumes++;TryOnController.visible=true;super.onResume();}protected void onPause(){pauses++;TryOnController.visible=false;super.onPause();}protected void onNewIntent(Intent intent){setIntent(intent);inspect();super.onNewIntent(intent);}}
